                nsumx %= n, nsumy %= n;
                ll x_sum = nsumx * INV1 % n, y_sum = nsumy * INV1 % n;
                ll x_t = ((x0 - x_sum) * INV2 % n + n) % n, y_t = ((y0 - y_sum) * INV2 % n + n) % n;
                if (a[x_t][y_t] == '.') {
                    cout << i + 1 << ' ' << j + 1 << ' ' << x_t + 1 << ' ' << y_t + 1 << endl;
                    goto b;
                }
            }
        b:
            ;
        }
